// Get AI Agent output
let raw = $json.output;

// Remove markdown code blocks if the AI ever adds them
raw = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// Convert the JSON string into a real JavaScript object
const data = JSON.parse(raw);

// Get all extracted tasks
const tasks = data.tasks || [];

// Convert every task into a clean individual n8n item
return tasks.map((task, index) => ({
  json: {
    task_id: `TASK-${String(index + 1).padStart(3, "0")}`,
    owner: task.owner || "Unassigned",
    action_item: task.action_item || "No task provided",
    due_date: task.due_date || "Not Specified",
    status: task.status || "Pending"
  }
}));

const tasks = $input.all().map(item => item.json);

let html = `
<h2 style="font-family:Arial;">Meeting Action Summary</h2>
<p style="font-family:Arial;">The following tasks were extracted from the meeting:</p>

<table style="border-collapse:collapse;width:100%;font-family:Arial;">
  <tr style="background:#f2f2f2;">
    <th style="border:1px solid #ddd;padding:10px;">Task ID</th>
    <th style="border:1px solid #ddd;padding:10px;">Owner</th>
    <th style="border:1px solid #ddd;padding:10px;">Action Item</th>
    <th style="border:1px solid #ddd;padding:10px;">Due Date</th>
    <th style="border:1px solid #ddd;padding:10px;">Status</th>
  </tr>
`;

tasks.forEach(task => {
  html += `
  <tr>
    <td style="border:1px solid #ddd;padding:10px;">
      ${task.task_id}
    </td>

    <td style="border:1px solid #ddd;padding:10px;">
      ${task.owner}
    </td>

    <td style="border:1px solid #ddd;padding:10px;">
      ${task.action_item}
    </td>

    <td style="border:1px solid #ddd;padding:10px;">
      ${task.due_date}
    </td>

    <td style="border:1px solid #ddd;padding:10px;">
      ${task.status}
    </td>
  </tr>
  `;
});

html += `
</table>

<p style="font-family:Arial;margin-top:20px;">
Please review the assigned tasks and complete them before the respective deadlines.
</p>

<p style="font-family:Arial;">
Regards,<br>
Automated Meeting-to-Action Workflow System
</p>
`;

return [
  {
    json: {
      subject: "Meeting Action Summary",
      html: html
    }
  }
];
